import { PipelineConfig } from './types';

export interface GdsPollingOptions {
  pollingIntervalMs: number;
  maxBatchSize: number;
  idleBackoffMs: number;
}

const DEFAULT_POLLING_INTERVAL_MS = 2000; // Current: 2s (too slow)
const OPTIMIZED_POLLING_INTERVAL_MS = 500; // Target: 500ms

export function createGdsPollingConfig(
  config: PipelineConfig
): GdsPollingOptions {
  const useOptimized = config.enableOptimizedPolling ?? true;

  return {
    pollingIntervalMs: useOptimized
      ? OPTIMIZED_POLLING_INTERVAL_MS
      : DEFAULT_POLLING_INTERVAL_MS,
    maxBatchSize: config.gdsBatchSize ?? 100,
    idleBackoffMs: useOptimized ? 1000 : 4000,
  };
}

export function validatePollingInterval(intervalMs: number): void {
  if (intervalMs < 100) {
    throw new Error(
      `GDS polling interval ${intervalMs}ms is below minimum (100ms). ` +
      `This may cause excessive CPU usage on the queue processor.`
    );
  }
  if (intervalMs > 5000) {
    throw new Error(
      `GDS polling interval ${intervalMs}ms exceeds maximum (5000ms). ` +
      `This will cause unacceptable queue wait latency.`
    );
  }
}

export interface StreamingDriverConfig {
  pollingIntervalMs: number;
  maxConcurrentStreams: number;
  bufferSizeBytes: number;
  idleTimeoutMs: number;
}

export const STREAMING_DEFAULTS: StreamingDriverConfig = {
  pollingIntervalMs: 500,        // Changed: was 1500ms, now 500ms
  maxConcurrentStreams: 16,
  bufferSizeBytes: 4 * 1024 * 1024,
  idleTimeoutMs: 30_000,
};

export function createStreamingConfig(
  overrides?: Partial<StreamingDriverConfig>
): StreamingDriverConfig {
  return { ...STREAMING_DEFAULTS, ...overrides };
}

