export interface BatchingConfig {
  windowMs: number;
  maxBatchRows: number;
  adaptiveScaling: boolean;
}

const MIN_WINDOW_MS = 50;
const MAX_WINDOW_MS = 2000;

export class AdaptiveBatcher {
  private currentWindowMs: number;
  private readonly maxBatchRows: number;
  private throughputHistory: number[] = [];

  constructor(config: BatchingConfig) {
    this.currentWindowMs = config.windowMs;
    this.maxBatchRows = config.maxBatchRows;
  }

  get windowMs(): number {
    return this.currentWindowMs;
  }

  recordBatch(rowCount: number, durationMs: number): void {
    const throughput = rowCount / (durationMs / 1000);
    this.throughputHistory.push(throughput);
    if (this.throughputHistory.length > 10) {
      this.throughputHistory.shift();
    }
  }

  adjustWindow(): void {
    if (this.throughputHistory.length < 3) return;
    const avg = this.throughputHistory.reduce((a, b) => a + b, 0)
      / this.throughputHistory.length;

    if (avg > this.maxBatchRows * 0.8) {
      this.currentWindowMs = Math.max(MIN_WINDOW_MS,
        this.currentWindowMs * 0.8);
    } else if (avg < this.maxBatchRows * 0.3) {
      this.currentWindowMs = Math.min(MAX_WINDOW_MS,
        this.currentWindowMs * 1.2);
    }
  }
}

export const DEFAULT_BATCHING: BatchingConfig = {
  windowMs: 200,           // Changed: was 500ms, now 200ms
  maxBatchRows: 10_000,
  adaptiveScaling: true,
};
